var i=`0090-placinta-cu-varza`;var t=`world-0090`;var o=`MD`;var a=`eastern-europe`;var r=4;var s=89;var l={en:`Plăcintă cu Varză`,ua:`Плацинда з капустою`};var g={en:`A classic dish from Moldova, featuring white cabbage, yellow onion, carrot. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Молдова. Основні складники: білоголова капуста, жовта цибуля, морква. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 25 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 25 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:25,i:[[`all-purpose-flour`,500,`g`],[`water`,220,`ml`],[`sunflower-oil`,35,`ml`],[`table-salt`,5,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:15,i:[[`white-cabbage`,600,`g`],[`yellow-onion`,160,`g`],[`carrot`,100,`g`],[`sunflower-oil`,35,`ml`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:12,i:[]},{en:`Bake in a preheated 180°C oven for about 35 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 35 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:35,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`unsalted-butter`,40,`g`]]}];var d={slug:i,id:t,country:`MD`,region:a,servings:4,minutes:89,title:l,text:g,steps:u};export{o as country,d as default,t as id,s as minutes,a as region,r as servings,i as slug,u as steps,g as text,l as title};